($$agent-allotment$$, NULL, $$[{"label":"Agent code","name":"code"},{"label":"Password","name":"password","type":"password"}]$$::jsonb, $$View seat and route allotment for a registered agent.$$, NULL, $$View allotment$$),
($$cancel-ticket$$, NULL, $$[{"label":"Ticket number","name":"ticket","placeholder":"e.g. 24051234567"},{"label":"Registered mobile","name":"mobile","placeholder":"10-digit number","type":"tel"}]$$::jsonb, $$Cancel a confirmed GSRTC ticket. Cancellation charges apply based on how far from departure you cancel; the balance is refunded to the original payment method.$$, $$Refunds are processed within 7–10 working days.$$, $$Find ticket to cancel$$),
