($$gsrtc-agent-login$$, $$https://www.gsrtc.in/OPRSWeb/preUserAuthenticate.do$$, $$[{"label":"Agent ID / username","name":"user"},{"label":"Password","name":"password","type":"password"}]$$::jsonb, $$Portal login for GSRTC booking agents.$$, NULL, $$Open agent portal$$),
($$new-agent-register$$, NULL, $$[{"label":"Full name","name":"name"},{"label":"Mobile","name":"mobile","type":"tel"},{"label":"Email","name":"email","type":"email"},{"label":"Preferred division","name":"division","options":["Ahmedabad","Vadodara","Surat","Rajkot","Bhavnagar","Mehsana","Other"],"type":"select"},{"label":"PAN","name":"pan"}]$$::jsonb, $$Apply to become an authorised GSRTC booking agent. We review applications and respond by email.$$, $$Registration is subject to GSRTC's franchisee terms & conditions.$$, $$Submit application$$),
($$new-commuter-bus-pass$$, NULL, $$[{"label":"Full name","name":"name"},{"label":"Mobile","name":"mobile","type":"tel"},{"label":"From (boarding point)","name":"from"},{"label":"To (destination)","name":"to"},{"label":"Pass type","name":"type","options":["Daily","Monthly","Quarterly","Student"],"type":"select"}]$$::jsonb, $$Apply for a new monthly commuter bus pass online. Bring the reference number and a photo ID to any bus station to collect the pass.$$, NULL, $$Apply for pass$$),
($$print-sms-ticket$$, NULL, $$[{"label":"Ticket number","name":"ticket","placeholder":"e.g. 24051234567"},{"label":"Registered mobile","name":"mobile","placeholder":"10-digit number","type":"tel"}]$$::jsonb, $$Reprint your e-ticket or resend it to your phone by SMS.$$, NULL, $$Retrieve ticket$$),
($$refund-complaint$$, NULL, $$[{"label":"Ticket number","name":"ticket","placeholder":"e.g. 24051234567"},{"label":"Registered mobile","name":"mobile","placeholder":"10-digit number","type":"tel"},{"label":"Email","name":"email","placeholder":"you@example.com","type":"email"},{"full":true,"label":"Describe the issue","name":"details","type":"textarea"}]$$::jsonb, $$Raise a complaint for a refund that has not been credited. Our team responds within 3 working days.$$, NULL, $$Submit complaint$$),
